def move_one_ball(arr):
    # An empty array or a single-element array is already sorted
    if len(arr) <= 1:
        return True

    # Find the index where the array is "rotated" (i.e., where the next element is smaller)
    rotation_point = -1
    for i in range(len(arr)):
        if arr[i] > arr[(i + 1) % len(arr)]:
            if rotation_point != -1:
                # More than one rotation point found, cannot be sorted by right shifts
                return False
            rotation_point = i + 1

    # If no rotation point was found, the array is already sorted
    if rotation_point == -1:
        return True

    # Check if the array can be sorted by starting from the rotation point
    return arr[rotation_point:] + arr[:rotation_point] == sorted(arr)

